print("[DEBUG] === XZ 파일 복원 및 해제 스크립트 시작 ===")
print(f"[DEBUG] 원본 헥스 데이터 길이 (문자열): {len(hex_data)}")

try:
    # 1. 헥스 문자열 다듬기
    print("[DEBUG] 헥스 문자열 공백 제거 중...")
    clean_hex = hex_data.replace(" ", "")
    print(f"[DEBUG] 공백 제거 완료. 데이터 길이: {len(clean_hex)}")

    # 2. 헥스 문자열을 바이트 객체로 변환
    print("[DEBUG] 바이트 변환(unhexlify) 시도 중...")
    byte_data = binascii.unhexlify(clean_hex)
    print(f"[DEBUG] 바이트 변환 완료. 총 {len(byte_data)} 바이트 생성됨")
    
    # 시그니처 검증
    signature = byte_data[:6].hex().upper()
    print(f"[DEBUG] 추출된 파일 시그니처 (앞 6바이트): {signature}")
    if signature == "FD377A585A00":
        print("[DEBUG] 시그니처 매칭 성공: 올바른 XZ 포맷입니다.")
    else:
        print("[DEBUG] 경고: XZ 시그니처와 일치하지 않습니다! 데이터가 손상되었을 수 있습니다.")

    # 3. XZ 압축 해제
    print("[DEBUG] lzma 모듈을 사용하여 압축 해제 시작...")
    decompressed_data = lzma.decompress(byte_data)
    print(f"[DEBUG] 압축 해제 성공! 해제된 원본 데이터 크기: {len(decompressed_data)} 바이트")
    
    # 4. 해제된 데이터의 새로운 헤더 확인
    new_header = decompressed_data[:8].hex().upper()
    print(f"[DEBUG] 해제된 파일의 헤더 (앞 8바이트): {new_header}")
    print("[DEBUG] 힌트: 이 헤더를 구글링하거나 HxD로 확인하여 어떤 파일(ELF, txt 등)인지 유추하세요.")

    # 5. 결과물 저장
    output_filename = "extracted_payload.bin"
    print(f"[DEBUG] 파일 저장 시도 중... (파일명: {output_filename})")
    with open(output_filename, "wb") as f:
        f.write(decompressed_data)
    print("[DEBUG] 파일 저장 완료.")

except lzma.LZMAError as e:
    print(f"[DEBUG] 압축 해제 중 에러 발생 (LZMAError): {e}")
    print("[DEBUG] 제공된 헥스 데이터가 끝까지 제공되지 않아 잘렸을(Truncated) 가능성이 높습니다.")
except Exception as e:
    print(f"[DEBUG] 예기치 않은 오류 발생: {e}")

